"""Court-deadline calculator with invented Harlan County rules.

Rules:
- Deadlines are computed in calendar days.
- If a computed deadline lands on a Saturday, Sunday, or court holiday,
  it rolls FORWARD to the next day that is none of those.
- Periods of 7 days or fewer count only business days from the start
  (weekends and court holidays skipped; the trigger day itself is not counted).
"""

import argparse
import sys
from datetime import date, timedelta

from holidays import is_court_holiday


def _roll_forward(d: date) -> date:
    """Roll forward past Saturdays, Sundays, and court holidays."""
    while d.weekday() >= 5 or is_court_holiday(d):
        d += timedelta(days=1)
    return d


def compute(trigger_date: date, days: int) -> date:
    """Compute the deadline date for a period of `days` starting on `trigger_date`."""
    if days <= 0:
        raise ValueError("days must be a positive integer")

    if days <= 7:
        # Count only business days (non-weekend, non-holiday) after the start.
        d = trigger_date
        counted = 0
        while counted < days:
            d += timedelta(days=1)
            if d.weekday() < 5 and not is_court_holiday(d):
                counted += 1
        return _roll_forward(d)

    # Calendar days.
    return _roll_forward(trigger_date + timedelta(days=days))


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        description="Compute Harlan County court deadlines."
    )
    parser.add_argument("trigger", help="Trigger date, YYYY-MM-DD")
    parser.add_argument("days", type=int, help="Number of days in the period")
    args = parser.parse_args(argv)

    try:
        trigger = date.fromisoformat(args.trigger)
    except ValueError:
        parser.error(f"invalid trigger date: {args.trigger!r} (expected YYYY-MM-DD)")

    try:
        print(compute(trigger, args.days).isoformat())
    except ValueError as exc:
        parser.error(str(exc))
    return 0


if __name__ == "__main__":
    sys.exit(main())

